fn numpy_append(arr: Vec<f32>, values: Vec<f32>) -> Vec<f32> {
    // Preallocate enough space for both vectors to avoid reallocations.
    let mut result = arr;
    result.reserve(values.len());
    // Extend `result` by consuming `values`.
    result.extend(values);
    result
}

